#include "NativeInputDelivery.hpp"
#include "NativeInputFixture.hpp"
#include "Pro40NativeReplay.hpp"
#include "SustainedInputReceiver.hpp"
#include <cassert>
#include <cstdio>
#include <fstream>
#include <memory>
using namespace Pro40Audio;

// Independent reproduction of the saved first-packet displacement. No recorded
// microphone values: test content is generated by NativeInputFixture.
static void displace(std::span<uint8_t> bytes) {
    assert(bytes.size()==360);
    std::move_backward(bytes.begin()+8,bytes.end()-4,bytes.end());
    std::fill_n(bytes.begin()+8,4,0);
}
int main(int argc,char **argv) {
    assert(argc==1 || argc==2);
    for(unsigned stream=0;stream<2;++stream)for(unsigned prefix=0;prefix<64;++prefix) {
        Pro40Packets::CaptureStartup parser;
        std::array<uint8_t,360> bytes{};
        const auto layout=Pro40Packets::capture[stream];
        Pro40Packets::write32(bytes.data(),3u<<24|uint32_t(layout.slots())<<16|248u);
        Pro40Packets::write32(bytes.data()+4,0x9002ffff);
        for(unsigned n=0;n<prefix;++n) {
            assert(parser.parse(std::span(bytes).first(8),stream,3));assert(!parser.preroll());
        }
        const auto payload=std::span(bytes).first(layout.dataBytes());
        Pro40Packets::write32(bytes.data()+4,0x90023000);
        assert(parser.parse(payload,stream,3) && parser.preroll()); // All content unavailable, not decoded.
        assert(parser.prerollOrdinal()==prefix && parser.badPcmLabels()==80);
        for(unsigned f=0;f<8;++f)for(unsigned c=0;c<layout.slots();++c)
            Pro40Packets::write32(bytes.data()+8+(f*layout.slots()+c)*4,c<10?0x40000000:0x80000000);
        bytes[3]=0;
        assert(parser.parse(payload,stream,3) && !parser.preroll());
        if(!stream) {
            bytes[8+10*4]=0x40;
            assert(!parser.parse(payload,stream,3)); // Later MIDI corruption never gets another pre-roll.
        }
    }
    // Header/shape/source/rate/SYT checks are not bypassed even on the first data.
    for(unsigned fault=0;fault<6;++fault) {
        Fixture::Source source;auto payload=source.next();
        if(fault==0)source.storage[0]=4;
        if(fault==1)source.storage[1]=12;
        if(fault==2)source.storage[4]=0;
        if(fault==3)source.storage[5]=1;
        if(fault==4)source.storage[7]=0xff,source.storage[6]=0x0f;
        if(fault==5)payload=payload.first(356);
        Pro40Packets::CaptureStartup parser;
        assert(!parser.parse(payload,0,3) && !parser.preroll());
    }
    for(bool displaced:{false,true}) {
        auto native=std::make_unique<Fixture::NativeSource>();
        auto handoff=std::make_unique<SustainedInputHandoff>(125,3);
        auto receiver=std::make_unique<SustainedInputReceiver<>>(*handoff,19);
        Pro40Packets::InputMonitor monitor;
        NativeInputDelivery delivery(4,3,7,monitor,handoff.get());
        Pro40Packets::NativeReplay replay(0,4,3,1,7,nullptr,nullptr,false);
        assert(handoff->clock(native->packets.clock(true)));
        NativePackets::PreparedBuffer owned;uint32_t status=0,stamp=0;
        std::array<uint8_t,448> output{};
        for(unsigned group=0;group<4;++group) {
            native->prepare();
            if(!group && displaced)displace(std::span(native->group[0].bytes).subspan(8,360));
            assert(native->append());
            assert(delivery.drain(native->queue.next(),7,[&](uint64_t n,auto &b,auto &s,auto &t) {
                return native->queue.observe(n,7,b,s,t);
            }));
            assert(handoff->clock(native->packets.clock()) && receiver->poll());
            for(unsigned n=group*64;n<(group+1)*64;++n) {
                assert(native->queue.copy(n,7,owned,status,stamp));
                assert(replay.ingest(owned.bytes,status,stamp,7)==Pro40Packets::NativeReplayError::none);
            }
            if(!group)assert(replay.start(1000,7)==Pro40Packets::ReplayError::none);
            for(unsigned n=group*64;n<(group+1)*64;++n) {
                const auto made=replay.produce(output,1000+n,7);assert(made);
                assert(Pro40Packets::parse(std::span(output).first(made.bytes),Pro40Packets::playback[0],1));
                for(size_t word=8;word<made.bytes;word+=4)
                    assert(!output[word+1] && !output[word+2] && !output[word+3]);
            }
        }
        assert(handoff->finish() && receiver->poll() && receiver->ended());
        assert(monitor.prerollFrames==8 && monitor.frames==native->packets.frames);
        assert(handoff->startup().prerollOrdinal()==0 && delivery.startup().prerollOrdinal()==0);
        assert(delivery.startup().shiftedLabels()==displaced);
        assert(delivery.startup().badPcmLabels()==(displaced?8:0));
        assert(delivery.startup().badMidiLabels()==(displaced?8:0));
        auto lease=receiver->tryAcquire();assert(lease && lease->oldest()==8);
        std::array<int32_t,8*8> pcm;pcm.fill(123);
        assert(lease->read(19,0,pcm)==WindowResult::stale);
        for(auto sample:pcm)assert(sample==0);
        assert(lease->read(19,8,pcm)==WindowResult::ok);
        for(unsigned f=0;f<8;++f)for(unsigned c=0;c<8;++c)assert(pcm[f*8+c]==Fixture::sample(8+f,c));
        for(const auto &channel:monitor.channels)assert(channel.firstNonzero==8);
    }
    std::puts("PASS: first data quarantined, displaced fixture, exact later PCM, unavailable frame range, unchanged replay timing and silence, strict later/header validation");
    if(argc==2) {
        // Optional private retained capture. Read only; print metadata, no PCM.
        std::ifstream raw(argv[1],std::ios::binary);assert(raw);
        Pro40Packets::CaptureStartup startup;Pro40Packets::Continuity continuity;
        unsigned checked=0;std::array<uint8_t,448> slot{};
        while(checked<64 && raw.read(reinterpret_cast<char *>(slot.data()),slot.size())) {
            const auto size=NativePackets::little32(slot.data()+4)>>16;
            assert(size<=440);auto payload=std::span(slot).subspan(8,size);
            const auto parsed=startup.parse(payload,0,0);assert(parsed && continuity.accept(parsed.packet));
            if(!startup.preroll()) {
                assert(Pro40Packets::parse(payload,Pro40Packets::capture[0],0));
            }
            ++checked;
        }
        assert(checked==64 && startup.prerollOrdinal()==1 && startup.shiftedLabels());
        assert(startup.badPcmLabels()==8 && startup.badMidiLabels()==8);
        std::puts("PASS: 64 archived packets, displaced initial data excluded, all subsequent labels and DBC valid");
    }
}
